(()=>{'use strict';const frames=[...document.querySelectorAll('iframe[data-kakao-src]')];function load(f){if(!f.dataset.kakaoSrc)return;f.src=f.dataset.kakaoSrc;delete f.dataset.kakaoSrc;}if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){load(e.target);observer.unobserve(e.target);}},{rootMargin:'300px 0px'});frames.forEach(f=>observer.observe(f));}else frames.forEach(load);window.addEventListener('message',e=>{if(!e.data||e.data.type!=='study-kakao-ready')return;const f=frames.find(f=>f.contentWindow===e.source&&f.dataset.mapKey===e.data.key);if(f)f.closest('.kakao-map-slot').setAttribute('data-map-ready','');});})();